const screens=[
  ["Campaigns","Campaign","campaign","Choose, create and safely manage campaign books."],
  ["Home","Village","base","Navigate the five opening places without mixing utilities into destinations."],
  ["Writing Desk","Writing","writing","Compose marks on the page and keep the bind decision reachable."],
  ["Storehouse","Village","inventory","Scan stored resources and items by identity, quantity and location."],
  ["Workshop","Making","station","Choose practical making work from a compact place surface."],
  ["Party","People","party","Compare travellers, roles, health, gear and planned Field Kit."],
  ["Essence Spring","Village","spring","Refine and unlearn through explicit, consequential transactions."],
  ["Constellation","Knowledge","constellation","Inspect one permanent reality-level purchase without a fake graph."],
  ["Library","Knowledge","library","Browse authored knowledge groups and open a stable anchored entry."],
  ["Bestiary","Knowledge","bestiary","Recognize species at a glance, then inspect known observations."],
  ["Research","Knowledge","research","Read a real prerequisite graph without flattening it into a list."],
  ["World History","Knowledge","history","Scan frozen world covers and compare any two records."],
  ["Blacksmith","Making","craft","Select exact inputs, preview cost and confirm a persistent result."],
  ["Trading Post","Village","trade","Compare offer, owned quantity and price without oversized rows."],
  ["Recycler","Making","recycler","Separate salvage recovery from merchant and forge interactions."],
  ["Tannery","Making","craft","Prepare hide-based equipment through the shared making grammar."],
  ["Bowyer","Making","craft","Build bows from explicit material profiles and truthful output preview."],
  ["Armoury","Making","armoury","Choose equipment profiles and inspect a compact material tray."],
  ["Weaponsmith","Making","craft","Build weapon families while comparison remains visible."],
  ["Scriptorium","Writing","scriptorium","Move among Hands, Inks and Runebook as sibling capabilities."],
  ["Survey Post","Knowledge","survey","Choose independent instrument studies without fake shared edges."],
  ["Apothecary","Making","apothecary","Prepare treatments with readiness and cost beside the action."],
  ["Reliquary","Knowledge","reliquary","Inspect singular recovered objects without inventory-wall styling."],
  ["Wayfarer’s Table","People","wayfarer","Review Sela’s three permanent fieldcraft benefits."],
  ["Anchorage","Village","anchorage","Show inactive, shortfall and reactivation facts together."],
  ["Distillery","Making","distillery","Separate process readiness from the resulting stored material."],
  ["Channelworks","Making","channelworks","Explain construction readiness and stale refusal in place."],
  ["Firepit","Village","firepit","Transfer and gather with exact capacity and placement truth."],
  ["Gear","People","gear","Compare candidate equipment to worn gear before the Equip action."],
  ["World","Expedition","world","Keep the map dominant while status, Field Kit and actions remain reachable."],
  ["Encounter","Expedition","combat","Keep the battlefield visible above a compact action palette."],
  ["Loot Decision","Expedition","loot","Compare Drop and Take symmetrically before committing."],
  ["Return Recap","Expedition","recap","Summarize recovered and lost exact identities without a new visual family."],
  ["Settings","Utility","settings","Keep utilities compact and clearly outside village navigation."]
].map(([title,category,type,purpose],index)=>({id:title.toLowerCase().replaceAll(/[^a-z0-9]+/g,"-"),title,category,type,purpose,index}));

const $=id=>document.getElementById(id),categories=["All",...new Set(screens.map(s=>s.category))];
const fixtureStatesByScreen={constellation:["Default","Selected","Confirm","Bought"]};
const reviewStorageKey="bookbinder.assetlab.ui-gallery-reviews.v1";
const fontChoices=[
  {id:"jersey-tiny",label:"Chosen · Jersey 10 + Tiny5"},
  {id:"pixelify",label:"Pixelify Sans · readable"},
  {id:"jersey",label:"Jersey 10 · compact"},
  {id:"silkscreen",label:"Silkscreen · crisp"},
  {id:"tiny5",label:"Tiny5 · tiny-grid"}
];
let active=screens[0],category="All",state="Default",query="";
let implementationReviews={};
let implementationDrafts={};
let reviewSaveState={screenID:"",state:"idle",message:""};
const marks={Campaign:"CB",Village:"VI",Writing:"IN",Making:"MK",People:"PE",Knowledge:"KN",Expedition:"EX",Utility:"UT"};
const notes={
  campaign:["Book covers are the identity; metadata remains compact.","Continue is primary; Delete is never adjacent or equal-weight."],
  base:["Home uses the authored scene; Make, Study and Realms retain truthful grids.","Party and Bind & Depart form a compact persistent bottom pair."],
  writing:["The page is the hero, not a toolbar.","Selection preview and bind action remain visible without a giant card."],
  inventory:["Six-across identities maximize recognition.","Selected detail is edge-clamped and quantity stays on the tile."],
  world:["The fixed-scale map owns most of the screen.","Narrative cannot displace Field Kit, resources or interaction buttons."],
  combat:["Battlefield remains visible while choosing actions.","Targets, technique ownership and consequences use separate cues."],
  default:["Compact context at top; one dominant work area.","Anchored detail and fixed action rail prevent sheet-within-sheet navigation."]
};

function top(title,purse="◆ 40") {return `<div class="safe-top"><span>10:22</span><span>● ◒ ▰</span></div><div class="phone-head"><h3>${title}</h3><span class="context-purse">${purse}</span></div>`}
function rail(primary="Continue",secondary="Back",danger=false,modifier=""){return `<div class="bottom-rail${modifier?` ${modifier}`:""}"><button class="pixel-btn">${secondary}</button><button class="pixel-btn ${danger?"danger":"primary"}">${primary}</button></div>`}
function glyph(icon,selected=false,locked=false,qty=""){return `<div class="tile${selected?" selected":""}${locked?" locked":""}"><span class="glyph">${icon}</span>${qty?`<span class="qty">${qty}</span>`:""}</div>`}
function row(icon,title,sub,tail=""){return `<div class="row"><span class="row-icon">${icon}</span><span><strong>${title}</strong><small>${sub}</small></span><span>${tail}</span></div>`}
function tabs(items,activeIndex=0){return `<div class="tab-row">${items.map((v,i)=>`<button class="tab ${i===activeIndex?"active":""}">${v}</button>`).join("")}</div>`}
function detail(title,body,stats=[]){return `<article class="detail"><span class="eyeline">Selected detail</span><h4>${title}</h4><p>${body}</p><div class="detail-stats">${stats.map(s=>`<span class="chip ${s.includes("+")?"good":""}">${s}</span>`).join("")}</div></article>`}
function phone(inner,dark=false){return `<div class="${dark?"dark":""}">${inner}</div>`}

function progressSpines(count){return Array.from({length:count},(_,i)=>`<i style="--volume-height:${24+(i%3)*4}px"><span>${i+1}</span></i>`).join("")}
function campaignBook({title,status,volumes,volumeLabel,health,level,place,played,progress,selected=false,legacy=false}){
  return `<article class="book-stack campaign-book${selected?" selected-book":""}${legacy?" legacy-book":""}"><div class="campaign-volume-row"><span class="book-spines" aria-label="${volumeLabel}">${progressSpines(volumes)}</span><span class="book-status">${status}</span></div><div class="campaign-info"><h4>${title}</h4><p class="campaign-vitals">${health} · Level ${level}</p><p class="campaign-place">${place} · ${played}</p><small class="book-progress">${progress}</small></div><span class="book-clasp" aria-hidden="true">${legacy?"×":selected?"◆":"◇"}</span></article>`;
}
function renderCampaign(){
  const books=[
    campaignBook({title:"Aimee’s Book",status:"READY",volumes:7,volumeLabel:"seven progress volumes",health:"13 / 13 health",level:4,place:"Base",played:"played today",progress:"Seven bound volumes",selected:true}),
    campaignBook({title:"Field Notes",status:"READY",volumes:4,volumeLabel:"four progress volumes",health:"8 / 11 health",level:2,place:"World",played:"played yesterday",progress:"Four bound volumes"}),
    campaignBook({title:"Old Test Book",status:"OLDER TEST VERSION",volumes:2,volumeLabel:"two legacy volumes",health:"Last recorded 10 / 10",level:1,place:"Format 12",played:"current format 13",progress:"Details · Export unchanged · confirmed Delete",legacy:true})
  ].join("");
  const detail=state==="Selected"?`<div class="campaign-detail"><span>Selected campaign</span><strong>Aimee’s Book</strong><small>Continue loads the newest playable campaign.</small></div>`:state==="Confirm"?`<div class="campaign-delete-confirm"><strong>Delete “Old Test Book”?</strong><small>The older test file is never overwritten. Export remains available.</small><div><button>Cancel</button><button class="danger">Delete campaign</button></div></div>`:`<div class="shelf-caption"><span>Selected campaign</span><strong>Aimee’s Book</strong><span>Older test books open details; they never load or overwrite.</span></div>`;
  return phone(top("Campaigns","3 campaign books")+`<div class="phone-content campaign-content"><div class="book-shelf">${books}</div>${detail}</div>`+rail("Continue Aimee’s Book","New Game"));
}
function renderBase(){return phone(top("Base","◆ 40 Essence · ✦ 0 Motes · ⚙")+`<div class="phone-content base-content"><div class="town-scene"><nav class="town-tabs" aria-label="Base districts">${tabs(["Home","Make","Study","Realms"])}</nav><span class="town-caption">Home · five places ready</span><button class="hotspot desk" style="--x:17%;--y:25%;--w:20%;--h:7%" data-route="writingDesk"><span><b>Writing Desk</b><small>compose</small></span></button><button class="hotspot work" style="--x:6%;--y:36%;--w:32%;--h:12%" data-route="workshop"><span><b>Workshop</b><small>make</small></span></button><button class="hotspot store" style="--x:59%;--y:26%;--w:34%;--h:12%" data-route="storehouse"><span><b>Storehouse</b><small>stored goods</small></span></button><button class="hotspot spring" style="--x:7%;--y:57%;--w:36%;--h:15%" data-route="essenceSpring"><span><b>Essence Spring</b><small>refine</small></span></button><button class="hotspot fire" style="--x:69%;--y:60%;--w:29%;--h:12%" data-route="firepit"><span><b>Firepit</b><small>gather</small></span></button></div></div>`+rail("Bind & Depart","Party",false,"home-actions"))}
function renderWriting(){return phone(top("Writing Desk","Brush · Ash")+`<div class="phone-content writing-content">${tabs(["Write","Pages","World"])}<div class="writing-layout writing-desk"><aside class="writing-tray writing-tool-rack"><span class="brush-rest" aria-label="Brush resting on the desk"><i></i></span><button class="rune-choice selected">☼<small>Sun</small></button><button class="rune-choice">≋<small>Smoke</small></button><button class="rune-choice">◆<small>Granite</small></button><button class="rune-choice">✤<small>Bloom</small></button><span class="inkwell" aria-label="Ash ink well">●</span><span class="eyeline">Hands · Inks · Runebook</span></aside><div class="page-sheet"><span class="page-cord"></span><span class="eyeline">Current page</span><div class="page-grid"><span class="connection-line"></span><span class="placed-rune sun">☼</span><span class="placed-rune smoke">≋</span></div><div class="page-caption"><span>2 marks · 1 connection</span><span>◆ 8</span></div></div></div></div>`+rail("Bind & Depart","Clear 2 marks",state==="Confirm"))}
function renderInventory(title="Storehouse"){const icons=["◈","▰","♨","✤","⬟","⌁","⚗","✦","◒","♢","⚒","◍"];return phone(top(title,"26 / 40 bins")+`<div class="phone-content storehouse-content">${tabs(["Resources","Items","Gear"])}<div class="storehouse-cabinet"><span class="cabinet-label">MATERIAL RESERVE · 12 FAMILIES</span><div class="tile-grid storage-grid">${icons.map((x,i)=>`<button class="stock-bin${i===1?" selected":""}"><span class="glyph">${x}</span><span class="qty">${(i%5)+1}</span><i></i></button>`).join("")}</div><span class="cabinet-plinth"></span></div><div class="storehouse-ledger"><article><span class="eyeline">Selected stock</span><strong>Obsidian ×3</strong><small>Material reserve</small></article><span class="ledger-route">→</span><article><span class="eyeline">Known work</span><strong>Depth ink</strong><small>Blacksmith</small></article></div>${state!=="Default"?detail("Obsidian","Dense volcanic glass. Exact stored identity remains visible in every consumer.",["3 stored","Depth"]):""}</div>`+rail("Inspect Obsidian","Sort"))}
function sceneFrame(kind,content){return `<div class="place-scene ${kind}"><div class="scene-sky"></div><div class="scene-floor"></div>${content}</div>`}
function fact(label,value,emphasis=""){return `<span class="fact ${emphasis}"><small>${label}</small><strong>${value}</strong></span>`}
function renderWorkshop(){return phone(top("Workshop","◆ 40")+`<div class="phone-content workshop-content">${tabs(["Projects","Pieces","Plans"])}${sceneFrame("workshop",`<span class="pegboard"><i class="saw"></i><i class="square-tool"></i><i class="mallet"></i></span><span class="workbench-top"></span><span class="frame-piece left"></span><span class="frame-piece right"></span><span class="frame-piece cross"></span><span class="timber-stack"><i></i><i></i><i></i></span><span class="wood-shavings">⌁ · ⌁</span><span class="scene-label">PRACTICAL WORKBENCH</span>`)}<div class="project-strip"><button class="project selected"><b>Field frame</b><small>ready</small></button><button class="project"><b>Storage brace</b><small>short 1</small></button><button class="project locked"><b>Unknown plan</b><small>locked</small></button></div><div class="receipt-line">${fact("Selected stock","Timber ×2")}${fact("Result","Field frame")}${fact("Cost","◆ 8")}</div></div>`+rail("Review project","Back"))}
function renderSpring(){return phone(top("Essence Spring","◆ 40 Essence")+`<div class="phone-content">${tabs(["Refine","Unlearn"])}<div class="spring-basin"><i class="spring-rune r1">◇</i><i class="spring-rune r2">✦</i><i class="spring-rune r3">⌁</i><span class="spring-water"></span><span class="spring-count">12 raw<br><b>→ 4 refined</b></span></div><div class="receipt-line">${fact("Before","40 Essence")}${fact("Refine","12 raw")}${fact("After","44 Essence","good")}</div><p class="process-copy">Refinement changes held resources. Unlearning is a separate permanent choice and never shares this action.</p></div>`+rail("Refine 12","Back"))}
function renderBlacksmith(){return phone(top("Blacksmith","Halloway · ◆ 40")+`<div class="phone-content">${tabs(["Construct","Reforge"])}${sceneFrame("forge",`<span class="prop furnace">♨</span><span class="prop anvil">▰</span><span class="prop hammer">⚒</span><span class="scene-label">HALLOWAY’S FORGE</span>`)}<div class="comparison-rack"><div><span class="eyeline">Retained piece</span><b>Bronze Fang</b><small>Tier 2 · reforge 1/3</small></div><span class="compare-arrow">→</span><div class="result"><span class="eyeline">After</span><b>Power 4.0</b><small>same exact piece</small></div></div><div class="receipt-line">${fact("Stock","Copper ×2")}${fact("Essence","12")}${fact("Change","+1 power","good")}</div></div>`+rail("Confirm reforge","Back"))}
function renderRecycler(){return phone(top("Recycler","Noll · 2 pieces")+`<div class="phone-content">${tabs(["Dismantle","Recovered"])}<div class="salvage-table"><div class="salvage-piece selected">⚔<small>Chipped blade</small></div><span class="salvage-teeth">⋮⋮⋮</span><div class="salvage-output"><span>◈ ×2</span><span>⌁ ×1</span></div></div><div class="receipt-line">${fact("Exact piece","Chipped blade")}${fact("Recover","3 units","good")}</div><p class="process-copy">The selected item is destroyed. Noll’s recovery preview is separate from merchant price and forge improvement.</p></div>`+rail("Review dismantle","Back"))}
function renderTannery(){return phone(top("Tannery","3 hides")+`<div class="phone-content">${tabs(["Stretch","Cut","Stored"])}<div class="hide-frame"><span class="hide-shape"></span><i class="tie t1"></i><i class="tie t2"></i><i class="tie t3"></i><i class="tie t4"></i><span class="scene-label">FLEXIBLE STOCK · WARM ORIGIN</span></div><div class="material-cards"><button class="sample selected">◒<b>Sun hide</b><small>warm · supple</small></button><button class="sample">◓<b>Marsh hide</b><small>cool · dense</small></button></div><div class="receipt-line">${fact("Selected","Sun hide")}${fact("Output","Leather ×2")}${fact("Origin","World 9")}</div></div>`+rail("Review tanning","Back"))}
function renderBowyer(){return phone(top("Bowyer","2 maintained sets")+`<div class="phone-content">${tabs(["Shape","Maintain","Materials"])}<div class="bow-jig"><span class="bow-limb left"></span><span class="bow-limb right"></span><span class="bow-string"></span><span class="grip"></span><span class="scene-label">STAVE TENSION</span></div><div class="profile-track"><span>Flexible</span><i><b style="width:68%"></b></i><span>Rigid</span></div><div class="receipt-line">${fact("Stave","Ash wood")}${fact("String","Sinew")}${fact("Profile","Long bow")}</div><p class="process-copy">Maintained ranged sets stay whole; this screen does not turn arrows into an ammunition chore.</p></div>`+rail("Review bow","Back"))}
function renderArmoury(){return phone(top("Armoury","4 protective pieces")+`<div class="phone-content">${tabs(["Profiles","Pieces","Materials"])}<div class="armour-stand"><span class="pauldron left"></span><span class="pauldron right"></span><span class="cuirass">⬟</span><span class="belt"></span><span class="scene-label">REINFORCED PROFILE</span></div><div class="profile-ribbon"><button>Light</button><button class="selected">Reinforced</button><button>Layered</button></div><div class="material-tray compact"><span class="material">◈ 2</span><span class="material">◒ 1</span><span class="material">⌁ 1</span></div><div class="receipt-line">${fact("Protection","3 → 5","good")}${fact("Weight","steady")}${fact("Cost","◆ 14")}</div></div>`+rail("Review rebuild","Back"))}
function renderWeaponsmith(){return phone(top("Weaponsmith","3 families")+`<div class="phone-content">${tabs(["Family","Profile","Stock"])}<div class="weapon-rack"><button class="weapon selected"><span>╱</span><b>Blade</b><small>near</small></button><button class="weapon"><span>†</span><b>Spear</b><small>reach</small></button><button class="weapon"><span>⌒</span><b>Hook</b><small>control</small></button></div><div class="profile-compass"><span class="might">MIGHT</span><i></i><span class="finesse">FINESSE</span><b style="left:62%"></b></div><div class="receipt-line">${fact("Material","Copper")}${fact("Family","Blade")}${fact("Power","3.5")}</div><p class="process-copy">Advice describes the profile. It does not lock the weapon to a wearer.</p></div>`+rail("Review weapon","Back"))}
function renderApothecary(){return phone(top("Apothecary","6 recipes known")+`<div class="phone-content">${tabs(["Treatments","Coatings","Fieldwork"])}<div class="bottle-shelf"><button class="bottle selected"><i class="round"></i><b>Lesser Salve</b><small>ready ×2</small></button><button class="bottle"><i class="tall"></i><b>Antidote</b><small>short Resin</small></button><button class="bottle"><i class="square"></i><b>Scent Mask</b><small>learned</small></button></div><div class="ingredient-line"><span>◈ Herb ×2</span><b>+</b><span>⌁ Resin ×1</span><b>→</b><span>⚗ ×2</span></div><div class="receipt-line">${fact("Stored","1 salve")}${fact("Prepare","2")}${fact("After","3 salves","good")}</div></div>`+rail("Prepare 2","Back"))}
function renderReliquary(){return phone(top("The Reliquary","Edren · fieldwork")+`<div class="phone-content"><article class="interpretation-board"><div class="interpretation-map" aria-hidden="true"><i></i><i></i><i></i><span>⌂</span></div><span class="eyeline">Permanent field interpretation</span><h4>Field interpretation</h4><div class="reliquary-benefits">${fact("Site locations","revealed on arrival","good")}${fact("Recovered resources","+1 each","good")}</div><p>Edren marks where a world shows signs of habitation. Reaching and searching each place is still fieldwork.</p></article></div>`)}
function renderWayfarer(){return phone(top("Wayfarer’s Table","Sela · fieldcraft")+`<div class="phone-content"><article class="card hero-card fieldcraft-board"><span class="eyeline">Permanent fieldcraft benefits</span><h4>Packed for the route</h4><div class="wayfarer-benefits">${fact("Satchel capacity","10 slots","good")}${fact("Organic harvests","+1 each","good")}${fact("Visible flora","identified on sight","good")}</div><p>Sela leaves routes, provisions and field notes here for whoever goes next. The table is useful precisely because nobody has to remain behind it.</p></article></div>`)}
function renderDistillery(){return phone(top("Distillery","Heat core · ember")+`<div class="phone-content">${tabs(["Distil","Crystallise","Stored"])}<div class="still"><span class="boiler">◉</span><span class="pipe"></span><span class="coil">≋</span><span class="receiver">◇</span><i class="heat">♨</i><span class="scene-label">ATTUNEMENT RETAINED</span></div><div class="process-gauges"><label>Heat<i><b style="width:72%"></b></i></label><label>Potency<i><b style="width:48%"></b></i></label></div><div class="receipt-line">${fact("Input","Ember extract")}${fact("Origin","World 7")}${fact("Result","Potency 3")}</div></div>`+rail("Review distillation","Back"))}
function renderChannelworks(){return phone(top("Channelworks","1 conduit planned")+`<div class="phone-content">${tabs(["Conduits","Cores","Receipts"])}<div class="conduit-diagram"><span class="core">◆</span><span class="channel c1"></span><span class="channel c2"></span><span class="channel c3"></span><i class="port p1">1</i><i class="port p2">2</i><i class="port p3">3</i><span class="scene-label">ONE EXACT CORE · THREE ROUTES</span></div><div class="receipt-line">${fact("Core","Ember glass")}${fact("Origin","World 7")}${fact("Status","Ready","good")}</div><p class="process-copy">Construction transfers this core’s attunement and origin. A stale stock change refuses in place.</p></div>`+rail("Construct conduit","Back"))}
function renderFirepit(){return phone(top("Firepit","3 travellers home")+`<div class="phone-content">${tabs(["Coming","Home","Realms"],1)}<div class="camp-circle"><span class="fire-flame">♨</span><button class="seat s1">♙<small>Binder</small></button><button class="seat s2">♞<small>Mara</small></button><button class="seat s3">♟<small>Quill</small></button><button class="seat s4 empty">+<small>1 space</small></button></div><div class="receipt-line">${fact("Home","3")}${fact("Capacity","4")}${fact("Selected","Mara")}</div><p class="process-copy">Gathering and transferring remain separate. Confirmation names the traveller and exact destination.</p></div>`+rail("Move traveller","Gather all"))}
function renderRecap(){return phone(top("Expedition return","World 12 closed")+`<div class="phone-content">${tabs(["Recovered","Lost"])}<div class="receipt-paper"><div class="receipt-heading"><b>FIELD RECEIPT</b><span>RUN 12</span></div><div class="receipt-items"><span>⌁ Resin <b>×4</b></span><span>◈ Copper <b>×2</b></span><span>⚗ Salve <b>×1</b></span><span class="lost">⚔ Chipped blade <b>lost</b></span></div><div class="receipt-total"><span>Storehouse</span><b>+3 families · 7 units</b></div></div><p class="process-copy">Property-bearing items remain exact instances. Legacy string receipts use fallback identity only.</p></div>`+rail("Return to Base","History"))}
function renderSettings(){return phone(top("Settings","Utility board")+`<div class="phone-content settings-content"><div class="utility-board"><button class="utility-tool"><span class="tool-figure gear-figure">⚙</span><b>Gameplay</b><small>ordinary controls</small></button><button class="utility-tool"><span class="tool-figure sound-figure">♫</span><b>Sound</b><small>music · effects</small></button><button class="utility-tool debug-tool"><span class="tool-figure">⌁</span><b>Testing tools</b><small>DEBUG build only</small></button><button class="utility-tool"><span class="tool-figure">?</span><b>Help</b><small>rules · controls</small></button></div><div class="utility-note"><span class="eyeline">Outside the village</span><p>Utilities live on one compact instrument board. They are never mistaken for places at Base.</p></div></div>`+rail("Done","Reset"))}
